#!/usr/bin/env node
const fs = require("node:fs");
const path = require("node:path");

const files = {
  "src/modules/accounting/types.ts": "import { CurrencyCode } from \"../../core/tax-engine/types.js\";\n\nexport type AccountNature = \"DEUDORA\" | \"ACREEDORA\";\n\nexport interface PcgeAccount {\n  code: string;\n  name: string;\n  element: 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 | 9;\n  nature: AccountNature;\n  level: \"ELEMENTO\" | \"CUENTA\" | \"SUBCUENTA\" | \"DIVISIONARIA\" | \"SUBDIVISIONARIA\";\n  isMoveable: boolean; // Solo se puede asentar en cuentas con movimiento (subdivisionarias o cuentas terminales)\n}\n\nexport type OriginDocumentType =\n  | \"CPE_SALE\" // Factura, Boleta o Nota de Crédito emitida\n  | \"PURCHASE\" // Comprobante de compra / gasto\n  | \"COLLECTION\" // Cobro a cliente\n  | \"PAYMENT\" // Pago a proveedor\n  | \"OPENING\" // Asiento de apertura\n  | \"ADJUSTMENT\" // Asiento de ajuste / regularización\n  | \"MANUAL\"; // Asiento manual\n\nexport interface OriginDocumentReference {\n  type: OriginDocumentType;\n  documentId: string;\n  cpeType?: string; // \"01\", \"03\", \"07\", \"08\"\n  series?: string;\n  correlative?: string | number;\n  fullNumber?: string;\n  entityDocNumber?: string;\n  entityName?: string;\n}\n\nexport interface JournalEntryLine {\n  lineNumber: number;\n  accountCode: string;\n  accountName: string;\n  debit: string; // \"0.00\"\n  credit: string; // \"0.00\"\n  glosa?: string;\n  costCenter?: string;\n  referenceDoc?: string;\n}\n\nexport interface JournalEntry {\n  id: string;\n  companyId: string;\n  accountingPeriod: string; // \"YYYY-MM\"\n  entryNumber: number; // Correlativo de asiento\n  entryDate: string; // \"YYYY-MM-DD\"\n  glosa: string; // Explicación de la operación\n  currency: CurrencyCode;\n  exchangeRate?: string;\n  originDocument?: OriginDocumentReference;\n  lines: JournalEntryLine[];\n  totalDebit: string;\n  totalCredit: string;\n  isBalanced: boolean;\n  isOpening?: boolean;\n  isClosing?: boolean;\n  createdAt: string;\n}\n\nexport interface CreateJournalEntryInput {\n  companyId: string;\n  accountingPeriod: string;\n  entryDate: string;\n  glosa: string;\n  currency?: CurrencyCode;\n  exchangeRate?: string;\n  originDocument?: OriginDocumentReference;\n  lines: Array<{\n    accountCode: string;\n    accountName?: string;\n    debit?: number | string;\n    credit?: number | string;\n    glosa?: string;\n    costCenter?: string;\n    referenceDoc?: string;\n  }>;\n}\n\n// Configuración contable para generar asientos automáticos\nexport interface AccountingAutomationConfig {\n  defaultReceivableAccount?: string; // Por defecto: \"1212\"\n  defaultPayableAccount?: string; // Por defecto: \"4212\"\n  defaultIgvAccount?: string; // Por defecto: \"40111\"\n  defaultSaleAccountMerchandise?: string; // Por defecto: \"70121\"\n  defaultSaleAccountServices?: string; // Por defecto: \"70221\"\n  defaultPurchaseAccountMerchandise?: string; // Por defecto: \"6011\"\n  defaultInventoryAccount?: string; // Por defecto: \"20111\"\n  defaultInventoryVariationAccount?: string; // Por defecto: \"6111\"\n  defaultAdminExpenseAccount?: string; // Por defecto: \"941\"\n  defaultSellingExpenseAccount?: string; // Por defecto: \"951\"\n  defaultImputableExpenseAccount?: string; // Por defecto: \"791\"\n  adminExpenseRatio?: number; // Porcentaje a gastos adm (ej. 0.50 para 50%)\n  sellingExpenseRatio?: number; // Porcentaje a gastos venta (ej. 0.50 para 50%)\n}\n\n// Libro Mayor\nexport interface GeneralLedgerMovement {\n  entryNumber: number;\n  entryDate: string;\n  glosa: string;\n  debit: string;\n  credit: string;\n  runningBalance: string;\n}\n\nexport interface GeneralLedgerAccount {\n  accountCode: string;\n  accountName: string;\n  totalDebit: string;\n  totalCredit: string;\n  debtorBalance: string; // Saldo deudor\n  creditorBalance: string; // Saldo acreedor\n  movements: GeneralLedgerMovement[];\n}\n\nexport interface GeneralLedger {\n  companyId: string;\n  accountingPeriod: string;\n  generatedAt: string;\n  totalDebit: string;\n  totalCredit: string;\n  accounts: GeneralLedgerAccount[];\n}\n\n// Balance de Comprobación (Sumas y Saldos)\nexport interface TrialBalanceRow {\n  accountCode: string;\n  accountName: string;\n  debitSum: string; // Sumas del Mayor: Debe\n  creditSum: string; // Sumas del Mayor: Haber\n  debtorBalance: string; // Saldos: Deudor\n  creditorBalance: string; // Saldos: Acreedor\n}\n\nexport interface TrialBalance {\n  companyId: string;\n  accountingPeriod: string;\n  generatedAt: string;\n  rows: TrialBalanceRow[];\n  totalDebitSum: string;\n  totalCreditSum: string;\n  totalDebtorBalance: string;\n  totalCreditorBalance: string;\n  isBalanced: boolean;\n}\n",
  "src/modules/accounting/pcge-catalog.ts": "import { PcgeAccount } from \"./types.js\";\n\n/**\n * Catálogo estándar del Plan Contable General Empresarial (PCGE 2019)\n * Resolución CNC N° 002-2019-EF/30\n */\nexport const PCGE_ACCOUNTS: Record<string, PcgeAccount> = {\n  // ELEMENTO 1: ACTIVO DISPONIBLE Y EXIGIBLE\n  \"10\": {\n    code: \"10\",\n    name: \"Efectivo y equivalentes de efectivo\",\n    element: 1,\n    nature: \"DEUDORA\",\n    level: \"CUENTA\",\n    isMoveable: false,\n  },\n  \"101\": {\n    code: \"101\",\n    name: \"Caja\",\n    element: 1,\n    nature: \"DEUDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: true,\n  },\n  \"104\": {\n    code: \"104\",\n    name: \"Cuentas corrientes en instituciones financieras\",\n    element: 1,\n    nature: \"DEUDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: false,\n  },\n  \"1041\": {\n    code: \"1041\",\n    name: \"Cuentas corrientes operativas\",\n    element: 1,\n    nature: \"DEUDORA\",\n    level: \"DIVISIONARIA\",\n    isMoveable: true,\n  },\n  \"12\": {\n    code: \"12\",\n    name: \"Cuentas por cobrar comerciales - Terceros\",\n    element: 1,\n    nature: \"DEUDORA\",\n    level: \"CUENTA\",\n    isMoveable: false,\n  },\n  \"121\": {\n    code: \"121\",\n    name: \"Facturas, boletas y otros comprobantes por cobrar\",\n    element: 1,\n    nature: \"DEUDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: false,\n  },\n  \"1212\": {\n    code: \"1212\",\n    name: \"Facturas, boletas y otros comprobantes por cobrar - Emitidas en cartera\",\n    element: 1,\n    nature: \"DEUDORA\",\n    level: \"DIVISIONARIA\",\n    isMoveable: true,\n  },\n  \"1213\": {\n    code: \"1213\",\n    name: \"Facturas, boletas y otros comprobantes por cobrar - En cobranza\",\n    element: 1,\n    nature: \"DEUDORA\",\n    level: \"DIVISIONARIA\",\n    isMoveable: true,\n  },\n  \"16\": {\n    code: \"16\",\n    name: \"Cuentas por cobrar diversas - Terceros\",\n    element: 1,\n    nature: \"DEUDORA\",\n    level: \"CUENTA\",\n    isMoveable: false,\n  },\n  \"167\": {\n    code: \"167\",\n    name: \"Tributos por acreditar\",\n    element: 1,\n    nature: \"DEUDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: false,\n  },\n  \"1673\": {\n    code: \"1673\",\n    name: \"IGV por acreditar en compras\",\n    element: 1,\n    nature: \"DEUDORA\",\n    level: \"DIVISIONARIA\",\n    isMoveable: true,\n  },\n\n  // ELEMENTO 2: ACTIVO REALIZABLE (INVENTARIOS)\n  \"20\": {\n    code: \"20\",\n    name: \"Mercaderías\",\n    element: 2,\n    nature: \"DEUDORA\",\n    level: \"CUENTA\",\n    isMoveable: false,\n  },\n  \"201\": {\n    code: \"201\",\n    name: \"Mercaderías manufacturadas\",\n    element: 2,\n    nature: \"DEUDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: false,\n  },\n  \"2011\": {\n    code: \"2011\",\n    name: \"Mercaderías manufacturadas - Costo\",\n    element: 2,\n    nature: \"DEUDORA\",\n    level: \"DIVISIONARIA\",\n    isMoveable: false,\n  },\n  \"20111\": {\n    code: \"20111\",\n    name: \"Mercaderías manufacturadas - Costo (Almacén principal)\",\n    element: 2,\n    nature: \"DEUDORA\",\n    level: \"SUBDIVISIONARIA\",\n    isMoveable: true,\n  },\n\n  // ELEMENTO 4: PASIVO (TRIBUTOS Y CUENTAS POR PAGAR)\n  \"40\": {\n    code: \"40\",\n    name: \"Tributos, contraprestaciones y aportes al sistema público de pensiones y de salud por pagar\",\n    element: 4,\n    nature: \"ACREEDORA\",\n    level: \"CUENTA\",\n    isMoveable: false,\n  },\n  \"401\": {\n    code: \"401\",\n    name: \"Gobierno nacional\",\n    element: 4,\n    nature: \"ACREEDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: false,\n  },\n  \"4011\": {\n    code: \"4011\",\n    name: \"Impuesto general a las ventas\",\n    element: 4,\n    nature: \"ACREEDORA\",\n    level: \"DIVISIONARIA\",\n    isMoveable: false,\n  },\n  \"40111\": {\n    code: \"40111\",\n    name: \"IGV - Cuenta propia\",\n    element: 4,\n    nature: \"ACREEDORA\",\n    level: \"SUBDIVISIONARIA\",\n    isMoveable: true,\n  },\n  \"4017\": {\n    code: \"4017\",\n    name: \"Impuesto a la renta\",\n    element: 4,\n    nature: \"ACREEDORA\",\n    level: \"DIVISIONARIA\",\n    isMoveable: false,\n  },\n  \"40171\": {\n    code: \"40171\",\n    name: \"Renta de tercera categoría (Pagos a cuenta)\",\n    element: 4,\n    nature: \"ACREEDORA\",\n    level: \"SUBDIVISIONARIA\",\n    isMoveable: true,\n  },\n  \"42\": {\n    code: \"42\",\n    name: \"Cuentas por pagar comerciales - Terceros\",\n    element: 4,\n    nature: \"ACREEDORA\",\n    level: \"CUENTA\",\n    isMoveable: false,\n  },\n  \"421\": {\n    code: \"421\",\n    name: \"Facturas, boletas y otros comprobantes por pagar\",\n    element: 4,\n    nature: \"ACREEDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: false,\n  },\n  \"4212\": {\n    code: \"4212\",\n    name: \"Facturas, boletas y otros comprobantes por pagar - Emitidas\",\n    element: 4,\n    nature: \"ACREEDORA\",\n    level: \"DIVISIONARIA\",\n    isMoveable: true,\n  },\n\n  // ELEMENTO 6: GASTOS POR NATURALEZA\n  \"60\": {\n    code: \"60\",\n    name: \"Compras\",\n    element: 6,\n    nature: \"DEUDORA\",\n    level: \"CUENTA\",\n    isMoveable: false,\n  },\n  \"601\": {\n    code: \"601\",\n    name: \"Mercaderías\",\n    element: 6,\n    nature: \"DEUDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: false,\n  },\n  \"6011\": {\n    code: \"6011\",\n    name: \"Mercaderías manufacturadas\",\n    element: 6,\n    nature: \"DEUDORA\",\n    level: \"DIVISIONARIA\",\n    isMoveable: true,\n  },\n  \"61\": {\n    code: \"61\",\n    name: \"Variación de inventarios\",\n    element: 6,\n    nature: \"ACREEDORA\",\n    level: \"CUENTA\",\n    isMoveable: false,\n  },\n  \"611\": {\n    code: \"611\",\n    name: \"Mercaderías\",\n    element: 6,\n    nature: \"ACREEDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: false,\n  },\n  \"6111\": {\n    code: \"6111\",\n    name: \"Mercaderías manufacturadas\",\n    element: 6,\n    nature: \"ACREEDORA\",\n    level: \"DIVISIONARIA\",\n    isMoveable: true,\n  },\n  \"63\": {\n    code: \"63\",\n    name: \"Gastos de servicios prestados por terceros\",\n    element: 6,\n    nature: \"DEUDORA\",\n    level: \"CUENTA\",\n    isMoveable: false,\n  },\n  \"631\": {\n    code: \"631\",\n    name: \"Transporte, correos y gastos de viaje\",\n    element: 6,\n    nature: \"DEUDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: false,\n  },\n  \"6311\": {\n    code: \"6311\",\n    name: \"Transporte de carga\",\n    element: 6,\n    nature: \"DEUDORA\",\n    level: \"DIVISIONARIA\",\n    isMoveable: true,\n  },\n  \"632\": {\n    code: \"632\",\n    name: \"Asesoría y consultoría\",\n    element: 6,\n    nature: \"DEUDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: false,\n  },\n  \"6321\": {\n    code: \"6321\",\n    name: \"Auditoría y consultoría\",\n    element: 6,\n    nature: \"DEUDORA\",\n    level: \"DIVISIONARIA\",\n    isMoveable: true,\n  },\n  \"636\": {\n    code: \"636\",\n    name: \"Servicios básicos\",\n    element: 6,\n    nature: \"DEUDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: false,\n  },\n  \"6361\": {\n    code: \"6361\",\n    name: \"Energía eléctrica\",\n    element: 6,\n    nature: \"DEUDORA\",\n    level: \"DIVISIONARIA\",\n    isMoveable: true,\n  },\n  \"6363\": {\n    code: \"6363\",\n    name: \"Agua\",\n    element: 6,\n    nature: \"DEUDORA\",\n    level: \"DIVISIONARIA\",\n    isMoveable: true,\n  },\n  \"6364\": {\n    code: \"6364\",\n    name: \"Teléfono e internet\",\n    element: 6,\n    nature: \"DEUDORA\",\n    level: \"DIVISIONARIA\",\n    isMoveable: true,\n  },\n  \"65\": {\n    code: \"65\",\n    name: \"Otros gastos de gestión\",\n    element: 6,\n    nature: \"DEUDORA\",\n    level: \"CUENTA\",\n    isMoveable: false,\n  },\n  \"659\": {\n    code: \"659\",\n    name: \"Otros gastos de gestión diversos\",\n    element: 6,\n    nature: \"DEUDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: true,\n  },\n\n  // ELEMENTO 7: INGRESOS POR NATURALEZA\n  \"70\": {\n    code: \"70\",\n    name: \"Ventas\",\n    element: 7,\n    nature: \"ACREEDORA\",\n    level: \"CUENTA\",\n    isMoveable: false,\n  },\n  \"701\": {\n    code: \"701\",\n    name: \"Mercaderías\",\n    element: 7,\n    nature: \"ACREEDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: false,\n  },\n  \"7012\": {\n    code: \"7012\",\n    name: \"Mercaderías - Venta local\",\n    element: 7,\n    nature: \"ACREEDORA\",\n    level: \"DIVISIONARIA\",\n    isMoveable: false,\n  },\n  \"70121\": {\n    code: \"70121\",\n    name: \"Mercaderías - Terceros (Venta local)\",\n    element: 7,\n    nature: \"ACREEDORA\",\n    level: \"SUBDIVISIONARIA\",\n    isMoveable: true,\n  },\n  \"702\": {\n    code: \"702\",\n    name: \"Servicios terminados\",\n    element: 7,\n    nature: \"ACREEDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: false,\n  },\n  \"70221\": {\n    code: \"70221\",\n    name: \"Servicios terminados - Terceros (Venta local)\",\n    element: 7,\n    nature: \"ACREEDORA\",\n    level: \"SUBDIVISIONARIA\",\n    isMoveable: true,\n  },\n  \"79\": {\n    code: \"79\",\n    name: \"Cargas imputables a cuentas de costos y gastos\",\n    element: 7,\n    nature: \"ACREEDORA\",\n    level: \"CUENTA\",\n    isMoveable: false,\n  },\n  \"791\": {\n    code: \"791\",\n    name: \"Cargas imputables a cuentas de costos y gastos\",\n    element: 7,\n    nature: \"ACREEDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: true,\n  },\n\n  // ELEMENTO 9: CONTABILIDAD ANALÍTICA DE EXPLOTACIÓN (COSTOS Y GASTOS POR FUNCIÓN)\n  \"94\": {\n    code: \"94\",\n    name: \"Gastos administrativos\",\n    element: 9,\n    nature: \"DEUDORA\",\n    level: \"CUENTA\",\n    isMoveable: false,\n  },\n  \"941\": {\n    code: \"941\",\n    name: \"Gastos de administración\",\n    element: 9,\n    nature: \"DEUDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: true,\n  },\n  \"95\": {\n    code: \"95\",\n    name: \"Gastos de ventas\",\n    element: 9,\n    nature: \"DEUDORA\",\n    level: \"CUENTA\",\n    isMoveable: false,\n  },\n  \"951\": {\n    code: \"951\",\n    name: \"Gastos de comercialización y ventas\",\n    element: 9,\n    nature: \"DEUDORA\",\n    level: \"SUBCUENTA\",\n    isMoveable: true,\n  },\n};\n\n/**\n * Obtiene la cuenta PCGE por su código o lanza error si no existe\n */\nexport function getPcgeAccount(code: string): PcgeAccount {\n  const account = PCGE_ACCOUNTS[code];\n  if (!account) {\n    throw new Error(`Cuenta contable PCGE no encontrada en el catálogo: ${code}`);\n  }\n  return account;\n}\n\n/**\n * Valida si el código existe y obtiene su nombre (o un default si se permite cuenta personalizada)\n */\nexport function resolveAccountName(code: string, customName?: string): string {\n  if (customName && customName.trim().length > 0) {\n    return customName.trim();\n  }\n  const account = PCGE_ACCOUNTS[code];\n  if (account) {\n    return account.name;\n  }\n  return `Cuenta ${code}`;\n}\n",
  "src/modules/accounting/entry-builder.ts": "import { Decimal } from \"decimal.js\";\nimport {\n  AccountingAutomationConfig,\n  CreateJournalEntryInput,\n  JournalEntry,\n  JournalEntryLine,\n  OriginDocumentReference,\n} from \"./types.js\";\nimport { resolveAccountName } from \"./pcge-catalog.js\";\nimport { CpeRecord } from \"../cpe/types.js\";\nimport { PurchaseDocumentRecord } from \"../purchases/types.js\";\n\nDecimal.set({ precision: 24, rounding: Decimal.ROUND_HALF_UP });\n\nconst round2 = (val: Decimal | number | string): string => {\n  return new Decimal(val).toFixed(2);\n};\n\nexport const DEFAULT_ACCOUNTING_CONFIG: Required<AccountingAutomationConfig> = {\n  defaultReceivableAccount: \"1212\",\n  defaultPayableAccount: \"4212\",\n  defaultIgvAccount: \"40111\",\n  defaultSaleAccountMerchandise: \"70121\",\n  defaultSaleAccountServices: \"70221\",\n  defaultPurchaseAccountMerchandise: \"6011\",\n  defaultInventoryAccount: \"20111\",\n  defaultInventoryVariationAccount: \"6111\",\n  defaultAdminExpenseAccount: \"941\",\n  defaultSellingExpenseAccount: \"951\",\n  defaultImputableExpenseAccount: \"791\",\n  adminExpenseRatio: 0.5,\n  sellingExpenseRatio: 0.5,\n};\n\n/**\n * Valida la partida doble de un asiento contable (Debe == Haber con precisión decimal)\n */\nexport function validateJournalEntryBalance(lines: JournalEntryLine[]): {\n  isBalanced: boolean;\n  totalDebit: string;\n  totalCredit: string;\n  difference: string;\n} {\n  if (!lines || lines.length === 0) {\n    throw new Error(\"El asiento contable debe tener al menos una línea\");\n  }\n\n  let totalDebit = new Decimal(0);\n  let totalCredit = new Decimal(0);\n\n  for (const line of lines) {\n    const d = new Decimal(line.debit || 0);\n    const c = new Decimal(line.credit || 0);\n\n    if (d.isNegative() || c.isNegative()) {\n      throw new Error(`Los importes de la línea ${line.lineNumber} no pueden ser negativos`);\n    }\n    if (d.isPositive() && c.isPositive() && !d.isZero() && !c.isZero()) {\n      throw new Error(\n        `La línea ${line.lineNumber} no puede tener importes simultáneos en el Debe y en el Haber`\n      );\n    }\n\n    totalDebit = totalDebit.plus(d);\n    totalCredit = totalCredit.plus(c);\n  }\n\n  const diff = totalDebit.minus(totalCredit).abs();\n  const isBalanced = diff.lessThan(0.005);\n\n  return {\n    isBalanced,\n    totalDebit: totalDebit.toFixed(2),\n    totalCredit: totalCredit.toFixed(2),\n    difference: diff.toFixed(2),\n  };\n}\n\n/**\n * Genera asiento contable automático a partir de un comprobante de venta (Factura 01, Boleta 03 o Nota de Crédito 07)\n */\nexport function buildSaleJournalEntry(\n  cpe: Pick<\n    CpeRecord,\n    | \"id\"\n    | \"companyId\"\n    | \"fullNumber\"\n    | \"cpeType\"\n    | \"series\"\n    | \"correlative\"\n    | \"issueDate\"\n    | \"currency\"\n    | \"clientDocNumber\"\n    | \"clientName\"\n    | \"subTotal\"\n    | \"montoIgv\"\n    | \"totalPagar\"\n  >,\n  config?: Partial<AccountingAutomationConfig>\n): CreateJournalEntryInput {\n  const cfg = { ...DEFAULT_ACCOUNTING_CONFIG, ...config };\n  const period = cpe.issueDate.substring(0, 7); // YYYY-MM\n  const isCreditNote = cpe.cpeType === \"07\";\n  const cpeName = cpe.cpeType === \"01\" ? \"Factura\" : cpe.cpeType === \"03\" ? \"Boleta\" : \"Nota de Crédito\";\n\n  const subTotal = new Decimal(cpe.subTotal || 0);\n  const montoIgv = new Decimal(cpe.montoIgv || 0);\n  const totalPagar = new Decimal(cpe.totalPagar || 0);\n\n  const lines: CreateJournalEntryInput[\"lines\"] = [];\n\n  const originDoc: OriginDocumentReference = {\n    type: \"CPE_SALE\",\n    documentId: cpe.id,\n    cpeType: cpe.cpeType,\n    series: cpe.series,\n    correlative: cpe.correlative,\n    fullNumber: cpe.fullNumber,\n    entityDocNumber: cpe.clientDocNumber,\n    entityName: cpe.clientName,\n  };\n\n  if (isCreditNote) {\n    // NOTA DE CRÉDITO: Disminución de ingresos y de la cuenta por cobrar\n    // Debe: 70121 (Venta)\n    lines.push({\n      accountCode: cfg.defaultSaleAccountMerchandise,\n      accountName: resolveAccountName(cfg.defaultSaleAccountMerchandise),\n      debit: round2(subTotal),\n      credit: \"0.00\",\n      glosa: `Anulación/Ajuste por ${cpeName} ${cpe.fullNumber}`,\n      referenceDoc: cpe.fullNumber,\n    });\n\n    // Debe: 40111 (IGV débito revertido)\n    if (montoIgv.greaterThan(0)) {\n      lines.push({\n        accountCode: cfg.defaultIgvAccount,\n        accountName: resolveAccountName(cfg.defaultIgvAccount),\n        debit: round2(montoIgv),\n        credit: \"0.00\",\n        glosa: `Reversión IGV por ${cpeName} ${cpe.fullNumber}`,\n        referenceDoc: cpe.fullNumber,\n      });\n    }\n\n    // Haber: 1212 (Cuentas por cobrar disminuidas)\n    lines.push({\n      accountCode: cfg.defaultReceivableAccount,\n      accountName: resolveAccountName(cfg.defaultReceivableAccount),\n      debit: \"0.00\",\n      credit: round2(totalPagar),\n      glosa: `Reversión cuenta por cobrar ${cpeName} ${cpe.fullNumber}`,\n      referenceDoc: cpe.fullNumber,\n    });\n  } else {\n    // FACTURA O BOLETA DE VENTA\n    // Debe: 1212 (Cuentas por cobrar)\n    lines.push({\n      accountCode: cfg.defaultReceivableAccount,\n      accountName: resolveAccountName(cfg.defaultReceivableAccount),\n      debit: round2(totalPagar),\n      credit: \"0.00\",\n      glosa: `Por cobrar según ${cpeName} ${cpe.fullNumber} - ${cpe.clientName}`,\n      referenceDoc: cpe.fullNumber,\n    });\n\n    // Haber: 40111 (IGV Cuenta Propia)\n    if (montoIgv.greaterThan(0)) {\n      lines.push({\n        accountCode: cfg.defaultIgvAccount,\n        accountName: resolveAccountName(cfg.defaultIgvAccount),\n        debit: \"0.00\",\n        credit: round2(montoIgv),\n        glosa: `IGV por venta ${cpe.fullNumber}`,\n        referenceDoc: cpe.fullNumber,\n      });\n    }\n\n    // Haber: 70121 (Venta neta)\n    lines.push({\n      accountCode: cfg.defaultSaleAccountMerchandise,\n      accountName: resolveAccountName(cfg.defaultSaleAccountMerchandise),\n      debit: \"0.00\",\n      credit: round2(subTotal),\n      glosa: `Venta según ${cpeName} ${cpe.fullNumber}`,\n      referenceDoc: cpe.fullNumber,\n    });\n  }\n\n  return {\n    companyId: cpe.companyId,\n    accountingPeriod: period,\n    entryDate: cpe.issueDate,\n    glosa: `Por la emisión de ${cpeName} ${cpe.fullNumber} a ${cpe.clientName}`,\n    currency: cpe.currency,\n    originDocument: originDoc,\n    lines,\n  };\n}\n\n/**\n * Genera asiento contable automático de compras (Provisión por Naturaleza y Asiento de Destino)\n */\nexport function buildPurchaseJournalEntries(\n  purchase: PurchaseDocumentRecord,\n  config?: Partial<AccountingAutomationConfig>\n): {\n  provisionEntry: CreateJournalEntryInput;\n  destinationEntry?: CreateJournalEntryInput;\n} {\n  const cfg = { ...DEFAULT_ACCOUNTING_CONFIG, ...config };\n  const period = purchase.accountingPeriod;\n  const supplierName = purchase.supplier.name;\n  const docRef = `${purchase.docType === \"01\" ? \"Factura\" : \"Boleta\"} ${purchase.fullNumber}`;\n\n  // 1. ASIENTO DE PROVISIÓN (NATURALEZA)\n  const baseGravada = new Decimal(purchase.totals.baseGravadaExclusiva || 0)\n    .plus(new Decimal(purchase.totals.baseGravadaComun || 0));\n  const baseSinCredito = new Decimal(purchase.totals.baseGravadaSinCredito || 0);\n  const noGravadas = new Decimal(purchase.totals.adquisicionesNoGravadas || 0);\n  \n  // IGV con crédito fiscal\n  const igvConCredito = new Decimal(purchase.totals.igvGravadoExclusivo || 0)\n    .plus(new Decimal(purchase.totals.igvGravadoComun || 0));\n  \n  // IGV sin derecho a crédito fiscal (Art. 69 LIGV: se incorpora al costo/gasto)\n  const igvSinCredito = new Decimal(purchase.totals.igvGravadoSinCredito || 0);\n\n  // Total costo/gasto neto para la cuenta 60/63\n  // Base gravada + Base sin crédito + No gravadas + IGV sin crédito\n  const totalGastoNeto = baseGravada.plus(baseSinCredito).plus(noGravadas).plus(igvSinCredito);\n  const totalPagar = new Decimal(purchase.totals.totalAdquisicion || 0);\n\n  const originDoc: OriginDocumentReference = {\n    type: \"PURCHASE\",\n    documentId: purchase.id,\n    cpeType: purchase.docType,\n    series: purchase.series,\n    correlative: purchase.correlative,\n    fullNumber: purchase.fullNumber,\n    entityDocNumber: purchase.supplier.docNumber,\n    entityName: supplierName,\n  };\n\n  // Determinar cuenta de gasto: si los items indican clasificación '1' es mercadería (6011), sino servicios (63xx)\n  const isMerchandise = purchase.items.some(\n    (item) => !item.classification || item.classification === \"1\"\n  );\n  const expenseAccount = isMerchandise\n    ? cfg.defaultPurchaseAccountMerchandise\n    : \"6321\"; // Asesoría/servicios\n\n  const provisionLines: CreateJournalEntryInput[\"lines\"] = [];\n\n  // Debe: 6011 / 63xx (Costo o Gasto por naturaleza)\n  provisionLines.push({\n    accountCode: expenseAccount,\n    accountName: resolveAccountName(expenseAccount),\n    debit: round2(totalGastoNeto),\n    credit: \"0.00\",\n    glosa: `Compra/Gasto según ${docRef} de ${supplierName}`,\n    referenceDoc: purchase.fullNumber,\n  });\n\n  // Debe: 40111 (IGV Crédito Fiscal)\n  if (igvConCredito.greaterThan(0)) {\n    provisionLines.push({\n      accountCode: cfg.defaultIgvAccount,\n      accountName: resolveAccountName(cfg.defaultIgvAccount),\n      debit: round2(igvConCredito),\n      credit: \"0.00\",\n      glosa: `IGV Crédito Fiscal por ${docRef}`,\n      referenceDoc: purchase.fullNumber,\n    });\n  }\n\n  // Haber: 4212 (Cuentas por pagar comerciales)\n  provisionLines.push({\n    accountCode: cfg.defaultPayableAccount,\n    accountName: resolveAccountName(cfg.defaultPayableAccount),\n    debit: \"0.00\",\n    credit: round2(totalPagar),\n    glosa: `Por pagar según ${docRef} a ${supplierName}`,\n    referenceDoc: purchase.fullNumber,\n  });\n\n  const provisionEntry: CreateJournalEntryInput = {\n    companyId: purchase.companyRuc,\n    accountingPeriod: period,\n    entryDate: purchase.issueDate,\n    glosa: `Por la provisión de compra según ${docRef} - ${supplierName}`,\n    currency: purchase.currency,\n    originDocument: originDoc,\n    lines: provisionLines,\n  };\n\n  // 2. ASIENTO DE DESTINO (TRANSFERENCIA)\n  let destinationEntry: CreateJournalEntryInput | undefined;\n\n  if (isMerchandise) {\n    // Destino de Mercaderías: 20111 (Debe) contra 6111 (Haber)\n    const destinationLines: CreateJournalEntryInput[\"lines\"] = [\n      {\n        accountCode: cfg.defaultInventoryAccount,\n        accountName: resolveAccountName(cfg.defaultInventoryAccount),\n        debit: round2(totalGastoNeto),\n        credit: \"0.00\",\n        glosa: `Ingreso al almacén por compra ${docRef}`,\n        referenceDoc: purchase.fullNumber,\n      },\n      {\n        accountCode: cfg.defaultInventoryVariationAccount,\n        accountName: resolveAccountName(cfg.defaultInventoryVariationAccount),\n        debit: \"0.00\",\n        credit: round2(totalGastoNeto),\n        glosa: `Variación de inventarios por compra ${docRef}`,\n        referenceDoc: purchase.fullNumber,\n      },\n    ];\n\n    destinationEntry = {\n      companyId: purchase.companyRuc,\n      accountingPeriod: period,\n      entryDate: purchase.issueDate,\n      glosa: `Por el destino de mercaderías al almacén según ${docRef}`,\n      currency: purchase.currency,\n      originDocument: originDoc,\n      lines: destinationLines,\n    };\n  } else {\n    // Destino de Gastos: 941 (Gastos Adm) y 951 (Gastos Ventas) contra 791 (Cargas Imputables)\n    const adminRatio = new Decimal(cfg.adminExpenseRatio);\n    const sellingRatio = new Decimal(cfg.sellingExpenseRatio);\n    const adminAmount = totalGastoNeto.mul(adminRatio);\n    const sellingAmount = totalGastoNeto.minus(adminAmount); // Asegurar exactitud decimal\n\n    const destinationLines: CreateJournalEntryInput[\"lines\"] = [\n      {\n        accountCode: cfg.defaultAdminExpenseAccount,\n        accountName: resolveAccountName(cfg.defaultAdminExpenseAccount),\n        debit: round2(adminAmount),\n        credit: \"0.00\",\n        glosa: `Gastos de administración por ${docRef}`,\n        referenceDoc: purchase.fullNumber,\n      },\n      {\n        accountCode: cfg.defaultSellingExpenseAccount,\n        accountName: resolveAccountName(cfg.defaultSellingExpenseAccount),\n        debit: round2(sellingAmount),\n        credit: \"0.00\",\n        glosa: `Gastos de ventas por ${docRef}`,\n        referenceDoc: purchase.fullNumber,\n      },\n      {\n        accountCode: cfg.defaultImputableExpenseAccount,\n        accountName: resolveAccountName(cfg.defaultImputableExpenseAccount),\n        debit: \"0.00\",\n        credit: round2(totalGastoNeto),\n        glosa: `Cargas imputables por gastos de ${docRef}`,\n        referenceDoc: purchase.fullNumber,\n      },\n    ];\n\n    destinationEntry = {\n      companyId: purchase.companyRuc,\n      accountingPeriod: period,\n      entryDate: purchase.issueDate,\n      glosa: `Por el destino de gastos de administración y ventas según ${docRef}`,\n      currency: purchase.currency,\n      originDocument: originDoc,\n      lines: destinationLines,\n    };\n  }\n\n  return { provisionEntry, destinationEntry };\n}\n\n/**\n * Genera asiento contable de tesorería (Cobranza a cliente o Pago a proveedor)\n */\nexport function buildTreasuryJournalEntry(params: {\n  companyId: string;\n  type: \"COLLECTION\" | \"PAYMENT\";\n  amount: number | string;\n  date: string;\n  treasuryAccount?: \"101\" | \"1041\"; // Caja o Banco\n  referenceDoc: string;\n  entityName: string;\n  glosa?: string;\n  currency?: \"PEN\" | \"USD\";\n}): CreateJournalEntryInput {\n  const period = params.date.substring(0, 7);\n  const amountStr = round2(params.amount);\n  const treasuryAccount = params.treasuryAccount || \"1041\";\n  const currency = params.currency || \"PEN\";\n\n  const lines: CreateJournalEntryInput[\"lines\"] = [];\n\n  if (params.type === \"COLLECTION\") {\n    // Cobranza: Ingresa dinero al Banco/Caja (Debe 10) y se cancela la cuenta por cobrar (Haber 1212)\n    lines.push({\n      accountCode: treasuryAccount,\n      accountName: resolveAccountName(treasuryAccount),\n      debit: amountStr,\n      credit: \"0.00\",\n      glosa: `Cobro en ${treasuryAccount === \"101\" ? \"caja\" : \"cuenta corriente\"} de ${params.entityName}`,\n      referenceDoc: params.referenceDoc,\n    });\n    lines.push({\n      accountCode: \"1212\",\n      accountName: resolveAccountName(\"1212\"),\n      debit: \"0.00\",\n      credit: amountStr,\n      glosa: `Cancelación cuenta por cobrar según ${params.referenceDoc}`,\n      referenceDoc: params.referenceDoc,\n    });\n  } else {\n    // Pago a proveedor: Se cancela la cuenta por pagar (Debe 4212) y sale dinero del Banco/Caja (Haber 10)\n    lines.push({\n      accountCode: \"4212\",\n      accountName: resolveAccountName(\"4212\"),\n      debit: amountStr,\n      credit: \"0.00\",\n      glosa: `Pago a proveedor ${params.entityName} por ${params.referenceDoc}`,\n      referenceDoc: params.referenceDoc,\n    });\n    lines.push({\n      accountCode: treasuryAccount,\n      accountName: resolveAccountName(treasuryAccount),\n      debit: \"0.00\",\n      credit: amountStr,\n      glosa: `Salida de ${treasuryAccount === \"101\" ? \"caja\" : \"cuenta corriente\"} por pago`,\n      referenceDoc: params.referenceDoc,\n    });\n  }\n\n  const defaultGlosa =\n    params.type === \"COLLECTION\"\n      ? `Por la cobranza de comprobante ${params.referenceDoc} - ${params.entityName}`\n      : `Por el pago de comprobante ${params.referenceDoc} a ${params.entityName}`;\n\n  return {\n    companyId: params.companyId,\n    accountingPeriod: period,\n    entryDate: params.date,\n    glosa: params.glosa || defaultGlosa,\n    currency,\n    lines,\n  };\n}\n",
  "src/modules/accounting/accounting-service.ts": "import { Decimal } from \"decimal.js\";\nimport {\n  CreateJournalEntryInput,\n  GeneralLedger,\n  GeneralLedgerAccount,\n  GeneralLedgerMovement,\n  JournalEntry,\n  JournalEntryLine,\n  TrialBalance,\n  TrialBalanceRow,\n} from \"./types.js\";\nimport { resolveAccountName } from \"./pcge-catalog.js\";\nimport { validateJournalEntryBalance } from \"./entry-builder.js\";\n\nDecimal.set({ precision: 24, rounding: Decimal.ROUND_HALF_UP });\n\nconst round2 = (val: Decimal | number | string): string => {\n  return new Decimal(val).toFixed(2);\n};\n\nexport class AccountingService {\n  private entries: JournalEntry[] = [];\n  private entrySequenceByPeriod: Map<string, number> = new Map();\n\n  constructor(initialEntries?: JournalEntry[]) {\n    if (initialEntries && initialEntries.length > 0) {\n      for (const e of initialEntries) {\n        this.registerEntry(e);\n      }\n    }\n  }\n\n  /**\n   * Registra un nuevo asiento contable en el Libro Diario validando su balance y asignando correlativo\n   */\n  public registerEntry(input: CreateJournalEntryInput | JournalEntry): JournalEntry {\n    if (!input.lines || input.lines.length === 0) {\n      throw new Error(\"No se puede registrar un asiento contable sin líneas\");\n    }\n\n    // Normalizar líneas asignando número de línea y resolviendo nombre de cuenta\n    const processedLines: JournalEntryLine[] = input.lines.map((l, index) => {\n      const debitStr = round2(l.debit ?? 0);\n      const creditStr = round2(l.credit ?? 0);\n      return {\n        lineNumber: index + 1,\n        accountCode: l.accountCode.trim(),\n        accountName: resolveAccountName(l.accountCode, l.accountName),\n        debit: debitStr,\n        credit: creditStr,\n        glosa: l.glosa,\n        costCenter: l.costCenter,\n        referenceDoc: l.referenceDoc,\n      };\n    });\n\n    // Validar partida doble innegociable\n    const balance = validateJournalEntryBalance(processedLines);\n    if (!balance.isBalanced) {\n      throw new Error(\n        `Asiento contable desbalanceado: Total Debe (${balance.totalDebit}) no es igual a Total Haber (${balance.totalCredit}). Diferencia: ${balance.difference}`\n      );\n    }\n\n    const periodKey = `${input.companyId}_${input.accountingPeriod}`;\n    const nextSeq = (this.entrySequenceByPeriod.get(periodKey) || 0) + 1;\n    this.entrySequenceByPeriod.set(periodKey, nextSeq);\n\n    const entryId =\n      \"id\" in input && input.id ? input.id : `entry_${input.companyId}_${input.accountingPeriod}_${nextSeq}`;\n\n    const journalEntry: JournalEntry = {\n      id: entryId,\n      companyId: input.companyId,\n      accountingPeriod: input.accountingPeriod,\n      entryNumber: \"entryNumber\" in input && input.entryNumber ? input.entryNumber : nextSeq,\n      entryDate: input.entryDate,\n      glosa: input.glosa,\n      currency: input.currency || \"PEN\",\n      exchangeRate: input.exchangeRate,\n      originDocument: input.originDocument,\n      lines: processedLines,\n      totalDebit: balance.totalDebit,\n      totalCredit: balance.totalCredit,\n      isBalanced: true,\n      createdAt: \"createdAt\" in input && input.createdAt ? input.createdAt : new Date().toISOString(),\n    };\n\n    this.entries.push(journalEntry);\n    return journalEntry;\n  }\n\n  /**\n   * Obtiene todos los asientos del Libro Diario para una empresa y periodo opcional\n   */\n  public getJournalEntries(companyId: string, period?: string): JournalEntry[] {\n    return this.entries.filter((e) => {\n      if (e.companyId !== companyId) return false;\n      if (period && e.accountingPeriod !== period) return false;\n      return true;\n    });\n  }\n\n  /**\n   * Busca un asiento por su documento de origen\n   */\n  public getEntryByOriginDocument(\n    companyId: string,\n    documentId: string\n  ): JournalEntry | undefined {\n    return this.entries.find(\n      (e) => e.companyId === companyId && e.originDocument?.documentId === documentId\n    );\n  }\n\n  /**\n   * Genera el Libro Mayor (General Ledger) agrupando movimientos por cuenta contable\n   */\n  public generateGeneralLedger(companyId: string, period: string): GeneralLedger {\n    const periodEntries = this.getJournalEntries(companyId, period).sort(\n      (a, b) => a.entryNumber - b.entryNumber\n    );\n\n    const accountMap = new Map<\n      string,\n      {\n        accountCode: string;\n        accountName: string;\n        movements: GeneralLedgerMovement[];\n        totalDebit: Decimal;\n        totalCredit: Decimal;\n      }\n    >();\n\n    let totalPeriodDebit = new Decimal(0);\n    let totalPeriodCredit = new Decimal(0);\n\n    for (const entry of periodEntries) {\n      for (const line of entry.lines) {\n        let accData = accountMap.get(line.accountCode);\n        if (!accData) {\n          accData = {\n            accountCode: line.accountCode,\n            accountName: line.accountName,\n            movements: [],\n            totalDebit: new Decimal(0),\n            totalCredit: new Decimal(0),\n          };\n          accountMap.set(line.accountCode, accData);\n        }\n\n        const debitDec = new Decimal(line.debit);\n        const creditDec = new Decimal(line.credit);\n\n        accData.totalDebit = accData.totalDebit.plus(debitDec);\n        accData.totalCredit = accData.totalCredit.plus(creditDec);\n\n        totalPeriodDebit = totalPeriodDebit.plus(debitDec);\n        totalPeriodCredit = totalPeriodCredit.plus(creditDec);\n\n        const currentNetBalance = accData.totalDebit.minus(accData.totalCredit);\n\n        accData.movements.push({\n          entryNumber: entry.entryNumber,\n          entryDate: entry.entryDate,\n          glosa: line.glosa || entry.glosa,\n          debit: line.debit,\n          credit: line.credit,\n          runningBalance: round2(currentNetBalance),\n        });\n      }\n    }\n\n    // Convertir a lista ordenada por código de cuenta\n    const accounts: GeneralLedgerAccount[] = Array.from(accountMap.values())\n      .sort((a, b) => a.accountCode.localeCompare(b.accountCode))\n      .map((acc) => {\n        const net = acc.totalDebit.minus(acc.totalCredit);\n        const isDebtor = net.greaterThan(0);\n        const isCreditor = net.lessThan(0);\n\n        return {\n          accountCode: acc.accountCode,\n          accountName: acc.accountName,\n          totalDebit: round2(acc.totalDebit),\n          totalCredit: round2(acc.totalCredit),\n          debtorBalance: isDebtor ? round2(net) : \"0.00\",\n          creditorBalance: isCreditor ? round2(net.abs()) : \"0.00\",\n          movements: acc.movements,\n        };\n      });\n\n    return {\n      companyId,\n      accountingPeriod: period,\n      generatedAt: new Date().toISOString(),\n      totalDebit: round2(totalPeriodDebit),\n      totalCredit: round2(totalPeriodCredit),\n      accounts,\n    };\n  }\n\n  /**\n   * Genera el Balance de Comprobación (Sumas y Saldos)\n   */\n  public generateTrialBalance(companyId: string, period: string): TrialBalance {\n    const ledger = this.generateGeneralLedger(companyId, period);\n\n    let totalDebitSum = new Decimal(0);\n    let totalCreditSum = new Decimal(0);\n    let totalDebtorBalance = new Decimal(0);\n    let totalCreditorBalance = new Decimal(0);\n\n    const rows: TrialBalanceRow[] = ledger.accounts.map((acc) => {\n      const dSum = new Decimal(acc.totalDebit);\n      const cSum = new Decimal(acc.totalCredit);\n      const dBal = new Decimal(acc.debtorBalance);\n      const cBal = new Decimal(acc.creditorBalance);\n\n      totalDebitSum = totalDebitSum.plus(dSum);\n      totalCreditSum = totalCreditSum.plus(cSum);\n      totalDebtorBalance = totalDebtorBalance.plus(dBal);\n      totalCreditorBalance = totalCreditorBalance.plus(cBal);\n\n      return {\n        accountCode: acc.accountCode,\n        accountName: acc.accountName,\n        debitSum: acc.totalDebit,\n        creditSum: acc.totalCredit,\n        debtorBalance: acc.debtorBalance,\n        creditorBalance: acc.creditorBalance,\n      };\n    });\n\n    const sumDiff = totalDebitSum.minus(totalCreditSum).abs();\n    const balanceDiff = totalDebtorBalance.minus(totalCreditorBalance).abs();\n    const isBalanced = sumDiff.lessThan(0.005) && balanceDiff.lessThan(0.005);\n\n    return {\n      companyId,\n      accountingPeriod: period,\n      generatedAt: new Date().toISOString(),\n      rows,\n      totalDebitSum: round2(totalDebitSum),\n      totalCreditSum: round2(totalCreditSum),\n      totalDebtorBalance: round2(totalDebtorBalance),\n      totalCreditorBalance: round2(totalCreditorBalance),\n      isBalanced,\n    };\n  }\n}\n",
  "src/modules/accounting/index.ts": "export * from \"./types.js\";\nexport * from \"./pcge-catalog.js\";\nexport * from \"./entry-builder.js\";\nexport * from \"./accounting-service.js\";\n",
  "src/modules/__tests__/accounting.test.ts": "import { describe, it, expect, beforeEach } from \"vitest\";\nimport {\n  AccountingService,\n  PCGE_ACCOUNTS,\n  getPcgeAccount,\n  validateJournalEntryBalance,\n  buildSaleJournalEntry,\n  buildPurchaseJournalEntries,\n  buildTreasuryJournalEntry,\n} from \"../accounting/index.js\";\nimport { CpeRecord } from \"../cpe/types.js\";\nimport { PurchaseDocumentRecord } from \"../purchases/types.js\";\n\ndescribe(\"Módulo de Contabilidad PCGE (Plan Contable General Empresarial)\", () => {\n  describe(\"Catálogo de Cuentas PCGE\", () => {\n    it(\"debe contener las cuentas clave para el ciclo de compras y ventas\", () => {\n      expect(getPcgeAccount(\"101\").name).toBe(\"Caja\");\n      expect(getPcgeAccount(\"1041\").name).toBe(\"Cuentas corrientes operativas\");\n      expect(getPcgeAccount(\"1212\").name).toContain(\"Emitidas en cartera\");\n      expect(getPcgeAccount(\"40111\").name).toBe(\"IGV - Cuenta propia\");\n      expect(getPcgeAccount(\"4212\").name).toContain(\"Emitidas\");\n      expect(getPcgeAccount(\"6011\").name).toBe(\"Mercaderías manufacturadas\");\n      expect(getPcgeAccount(\"70121\").name).toContain(\"Mercaderías - Terceros\");\n      expect(getPcgeAccount(\"20111\").name).toContain(\"Mercaderías manufacturadas\");\n      expect(getPcgeAccount(\"6111\").name).toBe(\"Mercaderías manufacturadas\");\n      expect(getPcgeAccount(\"791\").name).toBe(\"Cargas imputables a cuentas de costos y gastos\");\n    });\n\n    it(\"lanza error al consultar una cuenta inexistente\", () => {\n      expect(() => getPcgeAccount(\"999999\")).toThrow(/no encontrada en el catálogo/);\n    });\n  });\n\n  describe(\"Validación de Partida Doble\", () => {\n    it(\"aprueba un asiento perfectamente balanceado\", () => {\n      const result = validateJournalEntryBalance([\n        {\n          lineNumber: 1,\n          accountCode: \"1212\",\n          accountName: \"Facturas por cobrar\",\n          debit: \"118.00\",\n          credit: \"0.00\",\n        },\n        {\n          lineNumber: 2,\n          accountCode: \"40111\",\n          accountName: \"IGV\",\n          debit: \"0.00\",\n          credit: \"18.00\",\n        },\n        {\n          lineNumber: 3,\n          accountCode: \"70121\",\n          accountName: \"Ventas\",\n          debit: \"0.00\",\n          credit: \"100.00\",\n        },\n      ]);\n\n      expect(result.isBalanced).toBe(true);\n      expect(result.totalDebit).toBe(\"118.00\");\n      expect(result.totalCredit).toBe(\"118.00\");\n      expect(result.difference).toBe(\"0.00\");\n    });\n\n    it(\"rechaza un asiento desbalanceado\", () => {\n      const result = validateJournalEntryBalance([\n        {\n          lineNumber: 1,\n          accountCode: \"1212\",\n          accountName: \"Facturas por cobrar\",\n          debit: \"120.00\",\n          credit: \"0.00\",\n        },\n        {\n          lineNumber: 2,\n          accountCode: \"70121\",\n          accountName: \"Ventas\",\n          debit: \"0.00\",\n          credit: \"100.00\",\n        },\n      ]);\n\n      expect(result.isBalanced).toBe(false);\n      expect(result.difference).toBe(\"20.00\");\n    });\n\n    it(\"rechaza líneas con importes negativos o simultáneos en Debe y Haber\", () => {\n      expect(() =>\n        validateJournalEntryBalance([\n          {\n            lineNumber: 1,\n            accountCode: \"1212\",\n            accountName: \"Facturas\",\n            debit: \"-50.00\",\n            credit: \"0.00\",\n          },\n        ])\n      ).toThrow(/no pueden ser negativos/);\n\n      expect(() =>\n        validateJournalEntryBalance([\n          {\n            lineNumber: 1,\n            accountCode: \"1212\",\n            accountName: \"Facturas\",\n            debit: \"100.00\",\n            credit: \"100.00\",\n          },\n        ])\n      ).toThrow(/no puede tener importes simultáneos/);\n    });\n  });\n\n  describe(\"Generación Automática de Asientos desde Ventas (CPE)\", () => {\n    it(\"genera asiento de venta para una Factura (01) con Debe 12 y Haber 40 y 70\", () => {\n      const mockCpe: Pick<\n        CpeRecord,\n        | \"id\"\n        | \"companyId\"\n        | \"fullNumber\"\n        | \"cpeType\"\n        | \"series\"\n        | \"correlative\"\n        | \"issueDate\"\n        | \"currency\"\n        | \"clientDocNumber\"\n        | \"clientName\"\n        | \"subTotal\"\n        | \"montoIgv\"\n        | \"totalPagar\"\n      > = {\n        id: \"cpe-uuid-1\",\n        companyId: \"20600000005\",\n        fullNumber: \"F001-00000001\",\n        cpeType: \"01\",\n        series: \"F001\",\n        correlative: 1,\n        issueDate: \"2026-03-15\",\n        currency: \"PEN\",\n        clientDocNumber: \"20123456786\",\n        clientName: \"CLIENTE INDUSTRIAL SAC\",\n        subTotal: \"1000.00\",\n        montoIgv: \"180.00\",\n        totalPagar: \"1180.00\",\n      };\n\n      const entry = buildSaleJournalEntry(mockCpe);\n      expect(entry.accountingPeriod).toBe(\"2026-03\");\n      expect(entry.lines).toHaveLength(3);\n\n      const line12 = entry.lines.find((l) => l.accountCode === \"1212\");\n      const line40 = entry.lines.find((l) => l.accountCode === \"40111\");\n      const line70 = entry.lines.find((l) => l.accountCode === \"70121\");\n\n      expect(line12?.debit).toBe(\"1180.00\");\n      expect(line12?.credit).toBe(\"0.00\");\n      expect(line40?.debit).toBe(\"0.00\");\n      expect(line40?.credit).toBe(\"180.00\");\n      expect(line70?.debit).toBe(\"0.00\");\n      expect(line70?.credit).toBe(\"1000.00\");\n    });\n\n    it(\"genera asiento inverso para una Nota de Crédito (07)\", () => {\n      const mockNc: Pick<\n        CpeRecord,\n        | \"id\"\n        | \"companyId\"\n        | \"fullNumber\"\n        | \"cpeType\"\n        | \"series\"\n        | \"correlative\"\n        | \"issueDate\"\n        | \"currency\"\n        | \"clientDocNumber\"\n        | \"clientName\"\n        | \"subTotal\"\n        | \"montoIgv\"\n        | \"totalPagar\"\n      > = {\n        id: \"nc-uuid-1\",\n        companyId: \"20600000005\",\n        fullNumber: \"FC01-00000001\",\n        cpeType: \"07\",\n        series: \"FC01\",\n        correlative: 1,\n        issueDate: \"2026-03-18\",\n        currency: \"PEN\",\n        clientDocNumber: \"20123456786\",\n        clientName: \"CLIENTE INDUSTRIAL SAC\",\n        subTotal: \"200.00\",\n        montoIgv: \"36.00\",\n        totalPagar: \"236.00\",\n      };\n\n      const entry = buildSaleJournalEntry(mockNc);\n      const line70 = entry.lines.find((l) => l.accountCode === \"70121\");\n      const line40 = entry.lines.find((l) => l.accountCode === \"40111\");\n      const line12 = entry.lines.find((l) => l.accountCode === \"1212\");\n\n      expect(line70?.debit).toBe(\"200.00\");\n      expect(line70?.credit).toBe(\"0.00\");\n      expect(line40?.debit).toBe(\"36.00\");\n      expect(line40?.credit).toBe(\"0.00\");\n      expect(line12?.debit).toBe(\"0.00\");\n      expect(line12?.credit).toBe(\"236.00\");\n    });\n  });\n\n  describe(\"Generación Automática de Asientos desde Compras\", () => {\n    it(\"genera asiento de provisión y destino para compra de mercaderías (60 contra 42 y 20 contra 61)\", () => {\n      const mockPurchase: PurchaseDocumentRecord = {\n        id: \"purch-1\",\n        car: \"2060000000501F0010000100000000000001\",\n        companyRuc: \"20600000005\",\n        accountingPeriod: \"2026-03\",\n        supplier: {\n          docType: \"6\",\n          docNumber: \"20123456786\",\n          name: \"PROVEEDOR MAYORISTA SAC\",\n        },\n        docType: \"01\",\n        series: \"F001\",\n        correlative: \"100\",\n        fullNumber: \"F001-00000100\",\n        issueDate: \"2026-03-10\",\n        currency: \"PEN\",\n        paymentMethod: \"CONTADO\",\n        isBancarizado: true,\n        canUseFiscalCredit: true,\n        totals: {\n          baseGravadaExclusiva: \"5000.00\",\n          igvGravadoExclusivo: \"900.00\",\n          baseGravadaComun: \"0.00\",\n          igvGravadoComun: \"0.00\",\n          baseGravadaSinCredito: \"0.00\",\n          igvGravadoSinCredito: \"0.00\",\n          adquisicionesNoGravadas: \"0.00\",\n          isc: \"0.00\",\n          icbper: \"0.00\",\n          otrosCargos: \"0.00\",\n          totalAdquisicion: \"5900.00\",\n          totalCreditoFiscal: \"900.00\",\n        },\n        items: [\n          {\n            id: \"item-1\",\n            description: \"Mercadería A\",\n            quantity: \"10\",\n            unitValue: \"500.00\",\n            netBase: \"5000.00\",\n            taxDestination: \"GRAVADO_EXCLUSIVO\",\n            classification: \"1\", // Mercadería\n            igvAmount: \"900.00\",\n            totalAmount: \"5900.00\",\n            hasFiscalCredit: true,\n          },\n        ],\n        sireStatus: \"ACEPTADO\",\n        createdAt: \"2026-03-10T10:00:00Z\",\n      };\n\n      const { provisionEntry, destinationEntry } = buildPurchaseJournalEntries(mockPurchase);\n\n      // Provisión\n      expect(provisionEntry.lines).toHaveLength(3);\n      const line60 = provisionEntry.lines.find((l) => l.accountCode === \"6011\");\n      const line40 = provisionEntry.lines.find((l) => l.accountCode === \"40111\");\n      const line42 = provisionEntry.lines.find((l) => l.accountCode === \"4212\");\n\n      expect(line60?.debit).toBe(\"5000.00\");\n      expect(line40?.debit).toBe(\"900.00\");\n      expect(line42?.credit).toBe(\"5900.00\");\n\n      // Destino al almacén\n      expect(destinationEntry).toBeDefined();\n      expect(destinationEntry?.lines).toHaveLength(2);\n      const line20 = destinationEntry?.lines.find((l) => l.accountCode === \"20111\");\n      const line61 = destinationEntry?.lines.find((l) => l.accountCode === \"6111\");\n\n      expect(line20?.debit).toBe(\"5000.00\");\n      expect(line61?.credit).toBe(\"5000.00\");\n    });\n\n    it(\"asigna el IGV sin derecho a crédito fiscal como costo/gasto (Art. 69 LIGV)\", () => {\n      const mockPurchaseSinCredito: PurchaseDocumentRecord = {\n        id: \"purch-sin-cred\",\n        car: \"2060000000501F0010000200000000000001\",\n        companyRuc: \"20600000005\",\n        accountingPeriod: \"2026-03\",\n        supplier: {\n          docType: \"6\",\n          docNumber: \"20123456786\",\n          name: \"PROVEEDOR SERVICIOS SAC\",\n        },\n        docType: \"01\",\n        series: \"F001\",\n        correlative: \"200\",\n        fullNumber: \"F001-00000200\",\n        issueDate: \"2026-03-12\",\n        currency: \"PEN\",\n        paymentMethod: \"CONTADO\",\n        isBancarizado: true,\n        canUseFiscalCredit: false,\n        totals: {\n          baseGravadaExclusiva: \"0.00\",\n          igvGravadoExclusivo: \"0.00\",\n          baseGravadaComun: \"0.00\",\n          igvGravadoComun: \"0.00\",\n          baseGravadaSinCredito: \"1000.00\",\n          igvGravadoSinCredito: \"180.00\",\n          adquisicionesNoGravadas: \"0.00\",\n          isc: \"0.00\",\n          icbper: \"0.00\",\n          otrosCargos: \"0.00\",\n          totalAdquisicion: \"1180.00\",\n          totalCreditoFiscal: \"0.00\",\n        },\n        items: [\n          {\n            id: \"item-2\",\n            description: \"Gasto sin crédito\",\n            quantity: \"1\",\n            unitValue: \"1000.00\",\n            netBase: \"1000.00\",\n            taxDestination: \"GRAVADO_SIN_CREDITO\",\n            classification: \"3\", // Gastos de administración\n            igvAmount: \"180.00\",\n            totalAmount: \"1180.00\",\n            hasFiscalCredit: false,\n          },\n        ],\n        sireStatus: \"ACEPTADO\",\n        createdAt: \"2026-03-12T10:00:00Z\",\n      };\n\n      const { provisionEntry, destinationEntry } = buildPurchaseJournalEntries(mockPurchaseSinCredito);\n\n      // La cuenta 6321 debe absorber la base (1000) + el IGV sin crédito (180) = 1180\n      const line63 = provisionEntry.lines.find((l) => l.accountCode === \"6321\");\n      const line40 = provisionEntry.lines.find((l) => l.accountCode === \"40111\");\n      const line42 = provisionEntry.lines.find((l) => l.accountCode === \"4212\");\n\n      expect(line63?.debit).toBe(\"1180.00\");\n      expect(line40).toBeUndefined(); // No hay crédito fiscal\n      expect(line42?.credit).toBe(\"1180.00\");\n\n      // Destino por función (Elemento 9): 50% 941 y 50% 951 contra 791\n      const line94 = destinationEntry?.lines.find((l) => l.accountCode === \"941\");\n      const line95 = destinationEntry?.lines.find((l) => l.accountCode === \"951\");\n      const line79 = destinationEntry?.lines.find((l) => l.accountCode === \"791\");\n\n      expect(line94?.debit).toBe(\"590.00\");\n      expect(line95?.debit).toBe(\"590.00\");\n      expect(line79?.credit).toBe(\"1180.00\");\n    });\n  });\n\n  describe(\"Asientos de Tesorería\", () => {\n    it(\"genera asiento de cobranza a cliente en cuenta corriente (Debe 1041, Haber 1212)\", () => {\n      const entry = buildTreasuryJournalEntry({\n        companyId: \"20600000005\",\n        type: \"COLLECTION\",\n        amount: \"1180.00\",\n        date: \"2026-03-20\",\n        treasuryAccount: \"1041\",\n        referenceDoc: \"F001-00000001\",\n        entityName: \"CLIENTE INDUSTRIAL SAC\",\n      });\n\n      expect(entry.lines).toHaveLength(2);\n      expect(entry.lines[0].accountCode).toBe(\"1041\");\n      expect(entry.lines[0].debit).toBe(\"1180.00\");\n      expect(entry.lines[1].accountCode).toBe(\"1212\");\n      expect(entry.lines[1].credit).toBe(\"1180.00\");\n    });\n\n    it(\"genera asiento de pago a proveedor (Debe 4212, Haber 1041)\", () => {\n      const entry = buildTreasuryJournalEntry({\n        companyId: \"20600000005\",\n        type: \"PAYMENT\",\n        amount: \"5900.00\",\n        date: \"2026-03-22\",\n        treasuryAccount: \"1041\",\n        referenceDoc: \"F001-00000100\",\n        entityName: \"PROVEEDOR MAYORISTA SAC\",\n      });\n\n      expect(entry.lines).toHaveLength(2);\n      expect(entry.lines[0].accountCode).toBe(\"4212\");\n      expect(entry.lines[0].debit).toBe(\"5900.00\");\n      expect(entry.lines[1].accountCode).toBe(\"1041\");\n      expect(entry.lines[1].credit).toBe(\"5900.00\");\n    });\n  });\n\n  describe(\"Integración Libro Diario, Libro Mayor y Balance de Comprobación\", () => {\n    let service: AccountingService;\n\n    beforeEach(() => {\n      service = new AccountingService();\n    });\n\n    it(\"ejecuta el ciclo contable completo con doble cuadre en el Balance de Comprobación\", () => {\n      const companyId = \"20600000005\";\n      const period = \"2026-03\";\n\n      // 1. Asiento de Venta: S/ 1,000 + IGV S/ 180 = S/ 1,180\n      const saleEntry = buildSaleJournalEntry({\n        id: \"cpe-1\",\n        companyId,\n        fullNumber: \"F001-00000001\",\n        cpeType: \"01\",\n        series: \"F001\",\n        correlative: 1,\n        issueDate: \"2026-03-05\",\n        currency: \"PEN\",\n        clientDocNumber: \"20123456786\",\n        clientName: \"CLIENTE A\",\n        subTotal: \"1000.00\",\n        montoIgv: \"180.00\",\n        totalPagar: \"1180.00\",\n      });\n      service.registerEntry(saleEntry);\n\n      // 2. Asiento de Cobranza del 100% de la venta\n      const collectionEntry = buildTreasuryJournalEntry({\n        companyId,\n        type: \"COLLECTION\",\n        amount: \"1180.00\",\n        date: \"2026-03-08\",\n        treasuryAccount: \"1041\",\n        referenceDoc: \"F001-00000001\",\n        entityName: \"CLIENTE A\",\n      });\n      service.registerEntry(collectionEntry);\n\n      // 3. Asiento de Compra de mercaderías: S/ 500 + IGV S/ 90 = S/ 590\n      const { provisionEntry, destinationEntry } = buildPurchaseJournalEntries({\n        id: \"purch-1\",\n        car: \"2060000000501F0010000100000000000001\",\n        companyRuc: companyId,\n        accountingPeriod: period,\n        supplier: { docType: \"6\", docNumber: \"20123456786\", name: \"PROVEEDOR B\" },\n        docType: \"01\",\n        series: \"F001\",\n        correlative: \"10\",\n        fullNumber: \"F001-00000010\",\n        issueDate: \"2026-03-10\",\n        currency: \"PEN\",\n        paymentMethod: \"CONTADO\",\n        isBancarizado: true,\n        canUseFiscalCredit: true,\n        totals: {\n          baseGravadaExclusiva: \"500.00\",\n          igvGravadoExclusivo: \"90.00\",\n          baseGravadaComun: \"0.00\",\n          igvGravadoComun: \"0.00\",\n          baseGravadaSinCredito: \"0.00\",\n          igvGravadoSinCredito: \"0.00\",\n          adquisicionesNoGravadas: \"0.00\",\n          isc: \"0.00\",\n          icbper: \"0.00\",\n          otrosCargos: \"0.00\",\n          totalAdquisicion: \"590.00\",\n          totalCreditoFiscal: \"90.00\",\n        },\n        items: [\n          {\n            description: \"Mercaderías\",\n            quantity: \"5\",\n            unitValue: \"100.00\",\n            netBase: \"500.00\",\n            taxDestination: \"GRAVADO_EXCLUSIVO\",\n            classification: \"1\",\n            igvAmount: \"90.00\",\n            totalAmount: \"590.00\",\n            hasFiscalCredit: true,\n          },\n        ],\n        sireStatus: \"ACEPTADO\",\n        createdAt: \"2026-03-10T10:00:00Z\",\n      });\n\n      service.registerEntry(provisionEntry);\n      if (destinationEntry) {\n        service.registerEntry(destinationEntry);\n      }\n\n      // 4. Asiento de Pago al proveedor\n      const paymentEntry = buildTreasuryJournalEntry({\n        companyId,\n        type: \"PAYMENT\",\n        amount: \"590.00\",\n        date: \"2026-03-15\",\n        treasuryAccount: \"1041\",\n        referenceDoc: \"F001-00000010\",\n        entityName: \"PROVEEDOR B\",\n      });\n      service.registerEntry(paymentEntry);\n\n      // Verificación en Libro Diario\n      const journalEntries = service.getJournalEntries(companyId, period);\n      expect(journalEntries).toHaveLength(5);\n      expect(journalEntries.map((e) => e.entryNumber)).toEqual([1, 2, 3, 4, 5]);\n\n      // Generación y verificación del Libro Mayor\n      const ledger = service.generateGeneralLedger(companyId, period);\n      expect(ledger.accounts.length).toBeGreaterThanOrEqual(6);\n\n      // Cuenta 1041: Entró 1,180 (Debe) y Salió 590 (Haber) -> Saldo Deudor S/ 590.00\n      const acc1041 = ledger.accounts.find((a) => a.accountCode === \"1041\");\n      expect(acc1041?.totalDebit).toBe(\"1180.00\");\n      expect(acc1041?.totalCredit).toBe(\"590.00\");\n      expect(acc1041?.debtorBalance).toBe(\"590.00\");\n      expect(acc1041?.creditorBalance).toBe(\"0.00\");\n\n      // Cuenta 1212: Emitida por 1,180 (Debe) y Cobrada por 1,180 (Haber) -> Saldo 0.00\n      const acc1212 = ledger.accounts.find((a) => a.accountCode === \"1212\");\n      expect(acc1212?.totalDebit).toBe(\"1180.00\");\n      expect(acc1212?.totalCredit).toBe(\"1180.00\");\n      expect(acc1212?.debtorBalance).toBe(\"0.00\");\n      expect(acc1212?.creditorBalance).toBe(\"0.00\");\n\n      // Cuenta 4212: Por pagar 590 (Haber) y Pagada 590 (Debe) -> Saldo 0.00\n      const acc4212 = ledger.accounts.find((a) => a.accountCode === \"4212\");\n      expect(acc4212?.totalDebit).toBe(\"590.00\");\n      expect(acc4212?.totalCredit).toBe(\"590.00\");\n      expect(acc4212?.debtorBalance).toBe(\"0.00\");\n      expect(acc4212?.creditorBalance).toBe(\"0.00\");\n\n      // Cuenta 40111: IGV Venta 180 (Haber) e IGV Compra 90 (Debe) -> Saldo Acreedor S/ 90.00 (IGV por pagar)\n      const acc40111 = ledger.accounts.find((a) => a.accountCode === \"40111\");\n      expect(acc40111?.totalDebit).toBe(\"90.00\");\n      expect(acc40111?.totalCredit).toBe(\"180.00\");\n      expect(acc40111?.debtorBalance).toBe(\"0.00\");\n      expect(acc40111?.creditorBalance).toBe(\"90.00\");\n\n      // Generación y verificación del Balance de Comprobación\n      const trialBalance = service.generateTrialBalance(companyId, period);\n\n      // Verificación innegociable de doble cuadre:\n      // 1. Total Debe == Total Haber\n      expect(trialBalance.totalDebitSum).toBe(trialBalance.totalCreditSum);\n      // 2. Total Saldo Deudor == Total Saldo Acreedor\n      expect(trialBalance.totalDebtorBalance).toBe(trialBalance.totalCreditorBalance);\n      expect(trialBalance.isBalanced).toBe(true);\n    });\n  });\n});\n"
};
const root = process.cwd();
for (const [relativePath, content] of Object.entries(files)) {
  const target = path.join(root, relativePath);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, content, "utf8");
  console.log(`Creado: ${relativePath}`);
}
console.log(`\nMódulo de contabilidad instalado (${Object.keys(files).length} archivos).`);
